class Solution:
    def average(self, salary: list[int]) -> float:
        return (sum(salary) - min(salary) - max(salary)) / (len(salary) - 2)

#include <vector>
#include <algorithm>
#include <numeric>

class Solution {
public:
    double average(std::vector<int>& salary) {
        int minVal = salary[0], maxVal = salary[0];
        long long sum = 0;
        for (int s : salary) {
            minVal = std::min(minVal, s);
            maxVal = std::max(maxVal, s);
            sum += s;
        }
        return (double)(sum - minVal - maxVal) / (salary.size() - 2);
    }
};

class Solution {
    public double average(int[] salary) {
        int minVal = salary[0], maxVal = salary[0];
        long sum = 0;
        for (int s : salary) {
            minVal = Math.min(minVal, s);
            maxVal = Math.max(maxVal, s);
            sum += s;
        }
        return (double)(sum - minVal - maxVal) / (salary.length - 2);
    }
}

var average = function(salary) {
    let minVal = salary[0], maxVal = salary[0], sum = 0;
    for (const s of salary) {
        minVal = Math.min(minVal, s);
        maxVal = Math.max(maxVal, s);
        sum += s;
    }
    return (sum - minVal - maxVal) / (salary.length - 2);
};
